import { Text, View } from 'react-native'
import { Image, ImageSource } from 'expo-image'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'

interface ProfileSectionProps {
	profileImage: ImageSource | null
	blurhash: string
	name: string
	email: string
}

export const ProfileSection = ({
	profileImage,
	blurhash,
	name,
	email
}: ProfileSectionProps) => {
	const { theme } = useTheme()

	return (
		<View style={styles.profileImageContainer}>
			<Image
				source={profileImage}
				style={styles.profileImage}
				placeholder={{ blurhash }}
			/>
			<View style={styles.profileInfoContainer}>
				<Text style={styles.profileName(theme)}>{name}</Text>
				<Text style={styles.profileEmail(theme)}>{email}</Text>
			</View>
		</View>
	)
}

const styles = defineStyles({
	profileImageContainer: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: 18
	},
	profileImage: {
		width: 44,
		height: 44,
		borderRadius: 50
	},
	profileInfoContainer: {
		flexDirection: 'column',
		gap: 6
	},
	profileName: (theme: Theme) => ({
		fontWeight: '500',
		color: colors[theme].gray[900]
	}),
	profileEmail: (theme: Theme) => ({
		fontWeight: '400',
		color: colors[theme].gray[400]
	})
})
